import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.Cyu1VozZ.js";const g=JSON.parse('{"title":"Writing a Note","description":"","frontmatter":{},"headers":[],"relativePath":"notes/writing-a-note.md","filePath":"notes/writing-a-note.md"}'),s={name:"notes/writing-a-note.md"};function n(r,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="writing-a-note" tabindex="-1">Writing a Note <a class="header-anchor" href="#writing-a-note" aria-label="Permalink to &quot;Writing a Note&quot;">​</a></h1><p>Notes are lightweight <strong>Markdown</strong> documents in Wafflebase. Unlike the word-processor Docs editor, a note is written as Markdown <em>source</em> on one side with a live rendered <em>preview</em> on the other — a fast way to jot down meeting notes, drafts, and technical documentation, with the same real-time collaboration as every other document type.</p><h2 id="create-a-note" tabindex="-1">Create a Note <a class="header-anchor" href="#create-a-note" aria-label="Permalink to &quot;Create a Note&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click the <strong>New</strong> dropdown button</li><li>Select <strong>New Note</strong></li></ol><p>A blank note opens with the editor and preview side by side.</p><h2 id="the-editor" tabindex="-1">The Editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The Editor&quot;">​</a></h2><p>The left pane is a Markdown source editor. Type standard Markdown and watch the right pane render it live as you go.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Project Kickoff</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Agenda</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Introductions</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Timeline review</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Next steps**</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">See the [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">design doc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) for details.</span></span></code></pre></div><p>The source pane is a full code editor, so a few things come with it:</p><ul><li><strong>Line numbers</strong> run down the left gutter</li><li><strong>Folding</strong> — a fold arrow appears in the gutter beside a heading or a fenced block; click it to collapse that section, and click again to expand it</li><li><strong>Find and replace</strong> — press <kbd>⌘F</kbd> / <kbd>Ctrl+F</kbd> for a search panel with a replace field. <kbd>⌘G</kbd> / <kbd>Ctrl+G</kbd> jumps to the next match, <kbd>Shift</kbd> with it to the previous, and <kbd>Esc</kbd> closes the panel</li></ul><h3 id="choose-your-view" tabindex="-1">Choose Your View <a class="header-anchor" href="#choose-your-view" aria-label="Permalink to &quot;Choose Your View&quot;">​</a></h3><p>Use the <strong>view</strong> dropdown at the right of the toolbar to switch between three modes:</p><ul><li><strong>Split</strong> — source editor and preview side by side (the default)</li><li><strong>Editor</strong> — Markdown source only, full width</li><li><strong>Preview</strong> — rendered output only</li></ul><p>In Split, the two panes are separated by a <strong>draggable divider</strong>: drag it left or right to give either side more room (it stops at 15% and 85%, so neither pane can be squeezed away). The panes also <strong>scroll together</strong> — scrolling the source moves the preview to the same relative position, and scrolling the preview moves the source. Both are Split-only; in Editor or Preview there is one pane and nothing to sync.</p><p>Your choice is remembered per browser, so the note opens the same way next time.</p><div class="warning custom-block"><p class="custom-block-title">Split isn&#39;t offered on a narrow window</p><p>Below 768 pixels — so most phones — <strong>Split</strong> is removed from the view menu; two side-by-side panes on a phone-width screen leave neither one usable. A stored Split preference opens as <strong>Editor</strong> instead, so you never land in a layout the menu can&#39;t get you out of.</p><p>A mode you pick on a narrow window is also deliberately <em>not</em> saved. It applies for that session only, and the preference you set on a wide screen is left untouched — so checking the preview on your phone doesn&#39;t cost you Split on your desktop.</p></div><h3 id="see-who-wrote-what" tabindex="-1">See Who Wrote What <a class="header-anchor" href="#see-who-wrote-what" aria-label="Permalink to &quot;See Who Wrote What&quot;">​</a></h3><p>The same <strong>view</strong> dropdown has a <strong>Show authors</strong> switch at the bottom. Turn it on and a narrow column appears to the left of the line numbers, naming whoever most recently edited each line. A run of consecutive lines by the same person is labelled once, at the top, so the column stays quiet. Hover a name to see it in full if it&#39;s been cut short.</p><p>Some lines are blank in that column: text written before this feature existed carries no authorship, and an editor who had no display name shows as <strong>Anonymous</strong>.</p><p>Like the view mode, the switch is remembered per browser. It isn&#39;t available in a note opened through a share link, which has no view menu.</p><div class="warning custom-block"><p class="custom-block-title">Your name is recorded whether or not you switch this on</p><p><strong>Show authors</strong> only decides what <em>you</em> see — it does not decide what you leave behind. Every editor&#39;s client stamps their display name onto the text they type, always, and that name is stored in the note&#39;s content rather than in the temporary presence data behind cursor labels.</p><p>That means it is permanent and public to the note: it stays for the life of the note, it is readable by anyone who can read the note at all — including someone opening a read-only share link anonymously — and turning the switch off later doesn&#39;t remove what&#39;s already recorded. Nothing rewrites a name out of the text after the fact.</p><p>Names are also <strong>self-reported</strong>: they come from whichever browser wrote the text, and no server verifies them, which is why the tooltip on a name says so. Read the column as a helpful hint about who wrote a line, not as proof.</p></div><h2 id="formatting-toolbar" tabindex="-1">Formatting Toolbar <a class="header-anchor" href="#formatting-toolbar" aria-label="Permalink to &quot;Formatting Toolbar&quot;">​</a></h2><p>When the editor is visible, a toolbar gives you one-click Markdown for the most common styles — you never have to remember the syntax.</p><p><strong>Undo / Redo</strong> step through your own edits, and are greyed out when there is nothing left to undo or redo.</p><h3 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h3><p>Select some text first, then click a button to wrap it:</p><table tabindex="0"><thead><tr><th>Button</th><th>Inserts</th><th>Result</th></tr></thead><tbody><tr><td><strong>B</strong></td><td><code>**text**</code></td><td><strong>Bold</strong></td></tr><tr><td><em>I</em></td><td><code>*text*</code></td><td><em>Italic</em></td></tr><tr><td><s>S</s></td><td><code>~~text~~</code></td><td><s>Strikethrough</s></td></tr><tr><td>Link</td><td><code>[text](url)</code></td><td>A hyperlink</td></tr></tbody></table><p>Bold, italic, strikethrough and link are <strong>toggles</strong>: they light up when the caret sits in text that already has that style, and clicking again removes it.</p><h3 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Inserts</th><th>Result</th></tr></thead><tbody><tr><td>Bullet list</td><td><code>- item</code></td><td>An unordered list</td></tr><tr><td>Numbered list</td><td><code>1. item</code></td><td>An ordered list</td></tr><tr><td>Checkbox</td><td><code>- [ ] item</code></td><td>A task-list item</td></tr><tr><td>Indent</td><td>Adds a level of nesting</td><td>A nested item</td></tr><tr><td>Outdent</td><td>Removes a level of nesting</td><td>A less nested item</td></tr></tbody></table><p>The three list buttons are toggles — clicking the one that is already lit turns the lines back into plain paragraphs, and clicking a different one converts between kinds (a numbered list becomes a checklist, and so on). <strong>Indent</strong> and <strong>Outdent</strong> are greyed out when the item cannot nest any further in that direction: the first item of a list has no sibling to nest under, and a top-level item has nothing to come out of.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Select several lines and any of these five buttons applies to all of them at once, as a single undo step. They work inside a blockquote too, marking the lines up within the quote rather than pulling them out of it.</p></div><h3 id="blocks" tabindex="-1">Blocks <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Inserts</th></tr></thead><tbody><tr><td>Quote</td><td><code>&gt; </code> in front of every selected line</td></tr><tr><td>Code block</td><td>A ``` fence around the selection</td></tr><tr><td>Foldout</td><td>A <code>&lt;details&gt;</code> / <code>&lt;summary&gt;</code> collapsible section</td></tr><tr><td>Table</td><td>A GFM table skeleton</td></tr><tr><td>Image</td><td>Uploads a picture and links it</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <strong>Insert table</strong> button shows a small grid — hover to choose the number of rows and columns, then click to drop in a ready-to-fill table. You can also paste or drag an image straight into the editor instead of using the <strong>Insert image</strong> button.</p></div><h2 id="what-the-preview-renders" tabindex="-1">What the Preview Renders <a class="header-anchor" href="#what-the-preview-renders" aria-label="Permalink to &quot;What the Preview Renders&quot;">​</a></h2><p>The preview supports <strong>GitHub-Flavored Markdown</strong> plus a few extras:</p><ul><li><strong>Tables</strong> — standard <code>| col | col |</code> GFM tables</li><li><strong>Task lists</strong> — <code>- [ ]</code> and <code>- [x]</code> render as checkboxes. Typing just <code>[ ]</code> (or <code>[x]</code>) at the start of a line and pressing space adds the <code>- </code> for you. In the preview, clicking anywhere on a task — the box or the text beside it — ticks and unticks it, and the change is written back into the Markdown source. A read-only view (a share link without edit rights) shows the boxes but leaves them fixed.</li><li><strong>Code blocks</strong> — fenced ``` blocks get syntax highlighting and a <strong>Copy</strong> button in the corner</li><li><strong>Math</strong> — inline <code>$…$</code> and block <code>$$…$$</code> render with KaTeX</li><li><strong>Diagrams</strong> — a <code>```mermaid</code> fence renders as a diagram instead of a code block (see <a href="#diagrams">Diagrams</a> below)</li><li><strong>Links, headings, lists, blockquotes, images</strong> — as you&#39;d expect</li></ul><h3 id="single-newlines-are-line-breaks" tabindex="-1">Single Newlines Are Line Breaks <a class="header-anchor" href="#single-newlines-are-line-breaks" aria-label="Permalink to &quot;Single Newlines Are Line Breaks&quot;">​</a></h3><p>One thing differs from standard Markdown: pressing <strong>Enter</strong> once breaks the line. In most Markdown, two lines separated by a single newline join into one paragraph and you need a blank line — or two trailing spaces — to force a break. Here, what you see in the source is what you get in the preview.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Roses are red</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Violets are blue</span></span></code></pre></div><p>renders as two lines, not one.</p><h3 id="diagrams" tabindex="-1">Diagrams <a class="header-anchor" href="#diagrams" aria-label="Permalink to &quot;Diagrams&quot;">​</a></h3><p>Open a fence with <code>mermaid</code> instead of a language name and the block renders as a live <a href="https://mermaid.js.org/" target="_blank" rel="noreferrer">Mermaid</a> diagram — flowcharts, sequence diagrams, class diagrams, and the rest:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```mermaid</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Draft --&gt; Review --&gt; Published</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><p>The diagram follows the editor&#39;s light or dark theme, and updates as you type. The rendering engine is fetched the first time a note needs it, so the first diagram on a page can take a moment to appear — until it does, you see the diagram&#39;s source.</p><p>A diagram that doesn&#39;t parse keeps its source on screen with the error printed above it, so a half-typed diagram never leaves a blank hole in the preview.</p><p>A few things are deliberately turned off, and say so on the block if you use them:</p><ul><li><strong>Nothing may load an external URL.</strong> Image shapes (<code>@{ img: … }</code>), sequence actor icons, <code>url(…)</code> and <code>@import</code> in diagram styling, and any HTML tag that fetches something are all refused</li><li><strong>Per-diagram configuration is ignored</strong> — <code>%%{init: …}%%</code> directives and YAML front matter inside the fence (including its <code>title:</code>) are stripped before the diagram is drawn</li><li><strong>Labels are plain text.</strong> Bold, italic and other HTML formatting inside a node label won&#39;t apply, though <code>&lt;br/&gt;</code> still breaks the line</li><li>A single fence is capped at 50,000 characters</li></ul><h3 id="raw-html" tabindex="-1">Raw HTML <a class="header-anchor" href="#raw-html" aria-label="Permalink to &quot;Raw HTML&quot;">​</a></h3><p>The preview does not render arbitrary HTML. Paste a <code>&lt;div&gt;</code>, a <code>&lt;script&gt;</code>, or a <code>style=</code> attribute into a note and it appears in the preview as the literal text you typed, escaped rather than executed. That&#39;s deliberate: a note is shared, and HTML written by one collaborator would otherwise run in everyone else&#39;s browser.</p><p>Two tags are allowlisted as exceptions, because Markdown has no syntax of its own for what they do:</p><ul><li><strong><code>&lt;details&gt;</code> / <code>&lt;summary&gt;</code></strong> — the collapsible section the <strong>Foldout</strong> toolbar button inserts. Put each tag on its own line, keep the summary on a single line, and use <code>&lt;details open&gt;</code> to have it start expanded. Everything between the tags is ordinary Markdown, so lists, fences, and nested foldouts all work</li><li><strong><code>&lt;img&gt;</code></strong> — the sized-image snippet people copy from GitHub, e.g. <code>&lt;img src=&quot;diagram.png&quot; alt=&quot;Diagram&quot; width=&quot;400&quot;&gt;</code>. Only <code>src</code>, <code>alt</code>, <code>width</code> and <code>height</code> are accepted, and the dimensions must be a plain number or a percentage</li></ul><p>Anything outside that — an extra attribute on the image, <code>width=&quot;400px&quot;</code>, a <code>style=</code>, a different tag — makes the whole snippet fall back to being shown as literal text. It&#39;s refused visibly rather than silently ignored, so you can see that it didn&#39;t take.</p><h2 id="keyboard-mode" tabindex="-1">Keyboard Mode <a class="header-anchor" href="#keyboard-mode" aria-label="Permalink to &quot;Keyboard Mode&quot;">​</a></h2><p>Prefer modal editing? Open the <strong>keyboard</strong> dropdown in the toolbar and switch from <strong>Default</strong> to <strong>Vim</strong>. Vim keybindings then apply inside the source editor. Like the view mode, this is remembered per browser.</p><p>Standard editing shortcuts work in Default mode:</p><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Undo</td><td>⌘+Z / Ctrl+Z</td></tr><tr><td>Redo</td><td>⌘+Shift+Z / Ctrl+Shift+Z</td></tr><tr><td>Select all</td><td>⌘+A / Ctrl+A</td></tr><tr><td>Copy / Cut / Paste</td><td>⌘+C·X·V / Ctrl+C·X·V</td></tr><tr><td>Indent the line or selection</td><td>Tab</td></tr><tr><td>Remove a level of indentation</td><td>Shift+Tab</td></tr><tr><td>Find and replace</td><td>⌘+F / Ctrl+F</td></tr><tr><td>Move focus out of the editor</td><td>Esc</td></tr></tbody></table><p><kbd>Tab</kbd> indents the text itself, which is not quite the toolbar&#39;s <strong>Indent</strong> button — that one re-nests a list item. Because <kbd>Tab</kbd> is taken, <kbd>Esc</kbd> is how you leave the editor with the keyboard alone; it only moves focus when nothing else is using it, so it closes the find panel or an open suggestion list first. In Vim mode, <kbd>Esc</kbd> belongs to Vim.</p><h2 id="collaborate-in-real-time" tabindex="-1">Collaborate in Real Time <a class="header-anchor" href="#collaborate-in-real-time" aria-label="Permalink to &quot;Collaborate in Real Time&quot;">​</a></h2><p>Notes sync live through Wafflebase&#39;s CRDT engine, just like sheets, docs, and slides. When a teammate opens the same note:</p><ul><li>Their edits appear instantly as they type</li><li>You see their <strong>cursor and text selection</strong> in their own color</li><li>No saving, refreshing, or merge step is ever needed</li></ul><p>Share a note the same way as any document — click <strong>Share</strong> in the header to create a view or edit link. See <a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a> for the full sharing flow.</p><h2 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h2><p>Notes are versioned like every other editable document type. Click the <strong>history</strong> icon in the header to browse earlier versions, open one read-only, and roll the note back. See <a href="/docs/guide/version-history.html">Version History</a>.</p><h2 id="rename-a-note" tabindex="-1">Rename a Note <a class="header-anchor" href="#rename-a-note" aria-label="Permalink to &quot;Rename a Note&quot;">​</a></h2><p>Click the note&#39;s title in the header to rename it. The new title appears in your workspace document list immediately.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Notes are ideal for content you&#39;d otherwise keep in a <code>README</code> or a Markdown scratchpad — release notes, runbooks, and specs — kept in sync with your team without leaving Wafflebase.</p></div>',68)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
